export const ExternalApiRegistry = {
  list(): readonly ExternalApiProviderDefinition[] {
    return PROVIDERS;
  },

  get(id: string): ExternalApiProviderDefinition | undefined {
    return PROVIDERS.find((provider) => provider.id === id);
  },

  snapshot(): ExternalApiRegistrySnapshot {
    return {
      generatedAt: new Date().toISOString(),
      providers: [...PROVIDERS],
    };
  },
};
